package com.swiftcart.service;
import com.swiftcart.dto.OrderRequest;import com.swiftcart.model.*;import com.swiftcart.repository.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.util.HashSet;
@Service public class OrderService {private final ProductRepository products;private final CustomerOrderRepository orders;public OrderService(ProductRepository p,CustomerOrderRepository o){products=p;orders=o;}@Transactional public CustomerOrder create(OrderRequest r){var seen=new HashSet<Long>();BigDecimal total=BigDecimal.ZERO;for(var line:r.getItems()){if(!seen.add(line.getProductId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Each product must appear only once.");Product p=products.findById(line.getProductId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found."));if(line.getQuantity()>p.getStock())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Not enough stock for "+p.getName());total=total.add(p.getPrice().multiply(BigDecimal.valueOf(line.getQuantity())));}CustomerOrder order=new CustomerOrder(r.getCustomerName().trim(),r.getEmail().trim().toLowerCase(),r.getDeliveryAddress().trim(),total);for(var line:r.getItems()){Product p=products.findById(line.getProductId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found."));p.setStock(p.getStock()-line.getQuantity());order.addItem(new OrderItem(p.getId(),p.getName(),line.getQuantity(),p.getPrice()));}return orders.save(order);}}
